/* =====================================================================
   SIMULADOR-CORE.JS
   Lógica de negócio central, compartilhada por proposta.html, analise.html,
   repasse_analise.html e os formulários.

   IMPORTANTE: antes esse cálculo existia DUPLICADO em proposta.html e
   analise.html, com números DIFERENTES em cada arquivo (bug identificado
   na avaliação anterior). Agora existe em um lugar só — qualquer alteração
   de regra deve ser feita aqui, e vale automaticamente pra tudo.
   ===================================================================== */

/* ================= TABELAS DE ENTRADA (Financiamento / Carta de Crédito) ================= */
/* Inalteradas em relação à ferramenta original. */

const tabelaEntradas = {
  veiculo: [
    3989.66, 4621.27, 5252.88, 5884.49, 6006.22, 6516.10, 6639.63,
    7147.71, 7273.05, 7779.32, 7906.46, 8539.87, 9066.72, 9173.29,
    9573.39, 9806.70, 10333.39, 10440.11, 11071.81, 11073.53, 11706.94,
