    18041.07, 19307.90, 20574.72, 21841.55, 23108.38, 24785.48
  ],
  veiculo25e: [
    17761.06, 19517.17, 21273.27, 23029.38, 24785.48, 26541.59, 28297.69,
    30053.81, 31809.91, 33566.02, 35322.12, 36303.05, 39913.36, 44496.73,
    47021.94, 47835.24, 48284.55, 49547.15, 50551.22, 50809.76, 51909.22,
    53267.21, 54625.20, 61415.16, 63435.83, 68205.13, 69748.86, 74995.09,
    76061.89, 81785.05, 82374.92, 88575.01, 88687.96, 95364.98
  ]
};

function entradaMaisProxima(lista, entrada) {
  const abaixo = lista.filter(e => e <= entrada);
  const valorAbaixo = abaixo.length > 0 ? Math.max(...abaixo) : null;

  const acimaDentro150 = lista.filter(e => e > entrada && e <= entrada + 150);
  const valorAcima = acimaDentro150.length > 0 ? Math.min(...acimaDentro150) : null;

  if (valorAbaixo === null && valorAcima === null) {
    const acimaDentro200 = lista.filter(e => e > entrada && e <= entrada + 200);
    return acimaDentro200.length > 0 ? Math.min(...acimaDentro200) : lista[0];
  }
  if (valorAbaixo === null) return valorAcima;
  if (valorAcima === null) return valorAbaixo;
  return (valorAcima - entrada) < (entrada - valorAbaixo) ? valorAcima : valorAbaixo;
}

/* ================= ADMINISTRADORAS (Autofinanciamento) =================
   PLACEHOLDER: valores de entrada e primeira parcela ainda não confirmados
   por você — preenchidos com números de exemplo só pra estrutura funcionar.
   Pra editar: troque os arrays "entradas" e "parcelas" de cada administradora
   (mesma posição no array = mesma faixa/par). Pode adicionar ou remover
   administradoras livremente — só relembrando a regra de comissão:
     nome contém "6"                       -> 0,6% supervisor / 1,2% vendedor
     nome contém "5" OU nome é "Volkswagen" -> 0,5% supervisor / 1,0% vendedor
*/

/* ================= TABELA ÚNICA (Autofinanciamento / Crédito para Quitação) =================
   Usada tanto no parcelamento tradicional quanto no repasse. Só existe uma
   entrada nesse objeto de propósito — é a tabela real que você passou.
   Pra editar: troque os arrays "entradas" e "parcelas" (mesma posição = mesmo par).
*/

const administradoras = {
  "GFT 6": {
    entradas: [4301.43, 4672.45, 4939.32, 5610.65, 5305.65, 5938.86, 6281.98, 6572.07, 6953.32, 7205.27, 7624.65, 7834.48, 8295.98, 10223.29, 10826.83, 12155.54, 12875.90, 14087.79, 14924.96, 16020.04, 16974.03, 18490.09, 20315.09, 23965.11, 25790.12, 27615.13, 29440.14, 33090.15, 36740.17],
    parcelas: [561.43, 342.45, 609.32, 690.65, 385.65, 428.86, 771.98, 472.07, 853.32, 515.27, 934.65, 558.48, 1015.98, 23.40, 1326.94, 855.67, 1825.11, 1120.21, 2074.20, 1623.99, 1782.38, 1623.99, 1782.38, 2099.18, 2257.58, 2415.98, 2574.38, 2891.17, 3207.97]
  }
};

/* Escolhe automaticamente a administradora/tabela mais próxima da entrada
   pedida pelo cliente — o vendedor não escolhe manualmente. */
function escolherAdministradora(entradaDesejada) {
  let melhor = null;
  let melhorDist = Infinity;
  for (const nome in administradoras) {
    const tab = administradoras[nome];
    for (let i = 0; i < tab.entradas.length; i++) {
      const dist = Math.abs(tab.entradas[i] - entradaDesejada);
      if (dist < melhorDist) {
        melhorDist = dist;
        melhor = { nome, entrada: tab.entradas[i], primeiraParcela: tab.parcelas[i] };
      }
    }
  }
  return melhor;
}

/* ================= COMISSÃO (só existe para Autofinanciamento) =================
   ASSUNÇÃO A CONFIRMAR: a % incide sobre o "valor do bem". Se for sobre o
   valor total ou a entrada, é só trocar o valorBase no calcularAutofinanciamento. */
function calcularComissao(nomeAdministradora, valorBase) {
  let supervisorPct = 0, vendedorPct = 0;
  if (nomeAdministradora.includes('6')) {
    supervisorPct = 0.006; vendedorPct = 0.012;
  } else if (nomeAdministradora.includes('5') || nomeAdministradora === 'Volkswagen') {
    supervisorPct = 0.005; vendedorPct = 0.010;
  }
  return {
    supervisorPct, vendedorPct,
    supervisor: valorBase * supervisorPct,
    vendedor: valorBase * vendedorPct
  };
}

/* ================= FORMATAÇÃO E MÁSCARAS ================= */

function fmt(n) {
  return Number(n || 0).toLocaleString('pt-BR', { minimumFractionDigits: 2, maximumFractionDigits: 2 });
}

function cpfMask(v) {
  v = v.replace(/\D/g, '');
  v = v.replace(/(\d{3})(\d)/, '$1.$2');
  v = v.replace(/(\d{3})(\d)/, '$1.$2');
  v = v.replace(/(\d{3})(\d{1,2})$/, '$1-$2');
  return v;
}

function rgMask(v) {
  // Sem validação rígida (não há padrão único de RG no Brasil) — só agrupamento visual.
  v = v.replace(/[^0-9A-Za-z]/g, '');
  v = v.replace(/(\w{2})(\w)/, '$1.$2');
  v = v.replace(/(\w{2})(\w)/, '$1.$2');
  v = v.replace(/(\w{3})(\w{1,2})$/, '$1-$2');
  return v;
}

function telefoneMask(v) {
  v = v.replace(/\D/g, '').slice(0, 11);
  if (v.length > 10) return v.replace(/(\d{2})(\d{5})(\d{0,4})/, '($1) $2-$3').trim().replace(/-$/, '');
  if (v.length > 5) return v.replace(/(\d{2})(\d{4})(\d{0,4})/, '($1) $2-$3').trim().replace(/-$/, '');
  if (v.length > 2) return v.replace(/(\d{2})(\d{0,5})/, '($1) $2');
  return v.replace(/(\d*)/, '($1');
}

function currencyMask(v) {
  v = v.replace(/\D/g, '');
  if (!v) return '';
  v = v.replace(/^0+(?=\d)/, '');
  const comMilhar = v.replace(/\B(?=(\d{3})+(?!\d))/g, '.');
  return 'R$ ' + comMilhar + ',00';
}

/* Liga a máscara de moeda a um campo de forma correta pra digitar E apagar.
   O ponto crítico: o próprio ",00" que a máscara acrescenta contém dígitos —
   se a gente reler TODOS os dígitos do campo a cada tecla, esse ",00" artificial
   entra na conta de novo e o número dispara. Por isso, só olhamos os dígitos
   ANTES da vírgula (a parte que o usuário realmente digita) e mantemos o
   cursor sempre logo antes da vírgula. */
function aplicarMascaraMoeda(id) {
  const el = document.getElementById(id);
  if (!el) return;
  el.addEventListener('input', () => {
    const antesDaVirgula = el.value.split(',')[0];
    const digitos = antesDaVirgula.replace(/\D/g, '');
    const novoValor = currencyMask(digitos);
    el.value = novoValor;
    const pos = novoValor.indexOf(',');
    if (pos > -1) {
      try { el.setSelectionRange(pos, pos); } catch (e) { /* ignora se o navegador não suportar aqui */ }
    }
  });
}

function validarEmail(email) {
  return /^[^\s@]+@[^\s@]+\.[^\s@]+$/.test(String(email || '').trim());
}

function parseCurrency(val) {
  return Number(String(val).replace(/[^0-9,]/g, '').replace(',', '.')) || 0;
}

/* ================= CÁLCULO: FINANCIAMENTO ================= */

function calcularFinanciamento(valorBem, entradaOriginal, parcelaDesejada) {
  const entradaFin = entradaOriginal + 2000;
  const saldoDevedorRuim = (valorBem - entradaFin) * 2.1;
  const totalRuim = saldoDevedorRuim + entradaFin;

  const prazosDisp = [60, 48, 36, 24, 12];
  let prazoRuim = 12;
  let parcelaRuim = saldoDevedorRuim / 12;

  for (const p of prazosDisp) {
    const tentativa = saldoDevedorRuim / p;
    if (tentativa >= parcelaDesejada + 300) {
      prazoRuim = p;
      parcelaRuim = tentativa;
      break;
    }
  }

  return {
    entrada: entradaFin,
    parcela: parcelaRuim,
    prazo: prazoRuim,
    prazoAnos: (prazoRuim / 12).toFixed(1),
    saldoDevedor: saldoDevedorRuim,
    total: totalRuim
  };
}

/* ================= CÁLCULO: AUTOFINANCIAMENTO (com administradora/comissão) ================= */

function calcularAutofinanciamento(valorBem, entradaOriginal, parcelaDesejada) {
  const admin = escolherAdministradora(entradaOriginal);
  const entrada = admin.entrada;
  const primeiraParcela = admin.primeiraParcela;
  const total = valorBem * 1.12;
  const parcela = parcelaDesejada - 25;
  const saldoDevedor = total - entrada;
  const prazo = parcela > 0 ? Math.ceil(saldoDevedor / parcela) : 0;
  const comissao = calcularComissao(admin.nome, valorBem);

  return {
    entrada, primeiraParcela, parcela, prazo,
    prazoAnos: (prazo / 12).toFixed(1),
    saldoDevedor, total,
    administradora: admin.nome,
    comissao
  };
}

/* ================= CÁLCULO: CARTA DE CRÉDITO ================= */

function calcularCartaCredito(valorBem, entradaOriginal, parcelaDesejada, tipoBem) {
  const entradaBoa = entradaMaisProxima(tabelaEntradas[tipoBem] || tabelaEntradas.veiculo, entradaOriginal);
  const entrada = entradaBoa - 3000;
  const total = valorBem * 1.11;
  const parcela = parcelaDesejada - 10;
  const saldoDevedor = total - entrada;
  const prazo = parcela > 0 ? Math.ceil(saldoDevedor / parcela) : 0;

  return {
    entrada, parcela, prazo,
    prazoAnos: (prazo / 12).toFixed(1),
    saldoDevedor, total
  };
}

/* ================= REPASSE: CATÁLOGO DE VEÍCULOS (placeholder) =================
   Sem backend ainda, então essa lista fica fixa aqui. Adicione/edite veículos
   à vontade — todos os campos que você pediu (modelo, ano, marca, km, valor
   do bem, valor final, entrada, parcelas, prazo, banco) estão presentes. */

const veiculosRepasse = [];

/* ================= REPASSE: LÓGICA DE REPROVAÇÃO =================
   Tabela final combinada e verificada com você (8 combinações, sem
   ambiguidade). Atual = Contém Declaração Atual. */

function avaliarReprovacaoRepasse(atual, pessoaFisica, pessoaJuridica) {
  if (pessoaFisica && pessoaJuridica && atual) {
    return ["ERROR 5776.AC"];
  }
  if (pessoaFisica && pessoaJuridica && !atual) {
    return ["DECLARAÇÃO INVÁLIDA", "ERROR 5776.AC"];
  }
  if (pessoaFisica && !pessoaJuridica) {
    return ["GRUPO DO CONSÓRCIADO INDISPONÍVEL PARA PESSOA FÍSICA", "ERROR 5776.AC"];
  }
  if (!atual && !pessoaFisica && !pessoaJuridica) {
    return ["DECLARAÇÃO NECESSÁRIA", "RENDA INCOMPATÍVEL"];
  }
  return ["ERROR 5776.AC"];
}

/* Causas de reprovação para o caminho Carteira Assinada (CLT) no Repasse. */
function causasReprovacaoCLT() {
  return ["DECLARAÇÃO NECESSÁRIA", "ERROR 5776.AC"];
}

/* ================= CADASTRO DE VEÍCULOS (IndexedDB) =================
   Sem backend, o "cadastro" fica salvo no navegador/aparelho onde foi
   feito (IndexedDB aguenta imagem tranquilamente, ao contrário do
   localStorage). Isso NÃO sincroniza entre aparelhos/pessoas — pra isso,
   só com um servidor de verdade (mesma conversa de antes). */

/* Se o IndexedDB não responder dentro do tempo (acontece em alguns navegadores
   ao abrir os arquivos direto, sem servidor), segue com um valor padrão em vez
   de deixar a página esperando pra sempre. */
function comLimiteDeTempo(promessa, ms, valorPadrao) {
  return Promise.race([
    promessa,
    new Promise((resolve) => setTimeout(() => resolve(valorPadrao), ms))
  ]);
}

function abrirBancoVeiculos() {
  return new Promise((resolve, reject) => {
    if (typeof indexedDB === 'undefined') {
      reject(new Error('IndexedDB indisponível neste navegador'));
      return;
    }
    const req = indexedDB.open('simuladorRepasseDB', 1);
    req.onupgradeneeded = (e) => {
      const db = e.target.result;
      if (!db.objectStoreNames.contains('veiculos')) {
        db.createObjectStore('veiculos', { keyPath: 'id' });
      }
    };
    req.onsuccess = (e) => resolve(e.target.result);
    req.onerror = (e) => reject(e.target.error);
  });
}

async function salvarVeiculoCadastrado(veiculo, imagemBlob) {
  const db = await comLimiteDeTempo(abrirBancoVeiculos(), 4000, null);
  if (!db) throw new Error('Não foi possível acessar o armazenamento local a tempo.');
  return new Promise((resolve, reject) => {
    const tx = db.transaction('veiculos', 'readwrite');
    tx.objectStore('veiculos').put(Object.assign({}, veiculo, { imagem: imagemBlob || null, cadastradoManualmente: true }));
    tx.oncomplete = () => resolve();
    tx.onerror = (e) => reject(e.target.error);
  });
}

async function carregarVeiculosCadastrados() {
  try {
    const db = await comLimiteDeTempo(abrirBancoVeiculos(), 3000, null);
    if (!db) return [];
    return await comLimiteDeTempo(new Promise((resolve, reject) => {
      const tx = db.transaction('veiculos', 'readonly');
      const req = tx.objectStore('veiculos').getAll();
      req.onsuccess = () => resolve(req.result || []);
      req.onerror = (e) => reject(e.target.error);
    }), 3000, []);
  } catch (e) {
    console.error('Erro ao carregar veículos cadastrados:', e);
    return [];
  }
}

async function excluirVeiculoCadastrado(id) {
  const db = await comLimiteDeTempo(abrirBancoVeiculos(), 4000, null);
  if (!db) throw new Error('Não foi possível acessar o armazenamento local a tempo.');
  return new Promise((resolve, reject) => {
    const tx = db.transaction('veiculos', 'readwrite');
    tx.objectStore('veiculos').delete(id);
    tx.oncomplete = () => resolve();
    tx.onerror = (e) => reject(e.target.error);
  });
}

/* Junta o catálogo fixo (veiculosRepasse) com os cadastrados no navegador. */
async function carregarCatalogoCompleto() {
  const cadastrados = await carregarVeiculosCadastrados();
  return [...veiculosRepasse, ...cadastrados];
}
